import{_ as a,H as e,f as t,i as r}from"./chunks/framework.Cvt1eIE0.js";const c=JSON.parse('{"title":"第五章 絶望","description":"","frontmatter":{},"headers":[],"relativePath":"story/3-2.md","filePath":"story/3-2.md"}'),o={name:"story/3-2.md"};function i(n,p,s,h,l,d){return e(),t("div",null,[...p[0]||(p[0]=[r('<h1 id="第五章-絶望" tabindex="-1">第五章 絶望 <a class="header-anchor" href="#第五章-絶望" aria-label="Permalink to &quot;第五章 絶望&quot;">​</a></h1><p>初戦。</p><p>世界連合軍は、敗北した。</p><p>撤退した兵士たちは、誰も口を開かなかった。</p><p>焚き火を囲んでも、笑い声はなかった。誰もが、目の前で消えた仲間の姿を、思い出していた。</p><p>「勝てるのか……？」</p><p>若い兵士が、震える声で呟いた。</p><p>その問いに、誰も、答えられなかった。</p><p>王都 GOLDEN BASTION。</p><p>作戦会議。</p><p>並んだ元帥たちの顔には、暗い影が落ちていた。</p><p>「通常兵器は、通用しません。」</p><p>「接近すら、不可能です。」</p><p>「戦力差が、大きすぎる。」</p><p>報告が一つ上がるたびに、室内の空気が、重くなった。</p><p>静寂。</p><p>長い、長い静寂が、会議室を支配した。</p><p>その時。</p><p>「なら。」</p><p>オーレックスが、立ち上がった。</p><p>「方法を探そう。」</p><p>「必ずある。」</p><p>それは、根拠のある言葉ではなかった。だが、ずっと昔から、何度も口にしてきた言葉だった。目の前の困りごとに、答えがないはずがない――そう信じて、村を救い、橋を架けてきた。今度も、同じだ。</p><p>その言葉に。</p><p>スターリンが、笑った。久しぶりの、いつもの笑い方だった。</p><p>「そうこなくっちゃな。」</p><p>ピックバーグも、微笑んだ。</p><p>「諦めるには、早い。」</p><hr><h1 id="第六章-古代文書" tabindex="-1">第六章 古代文書 <a class="header-anchor" href="#第六章-古代文書" aria-label="Permalink to &quot;第六章 古代文書&quot;">​</a></h1><p>エンド帝国図書館。</p><p>数千年分の記録が、棚を埋め尽くしていた。</p><p>ピックバーグと、エンド帝国の学者たちは、昼夜を問わず、調査を続けていた。</p><p>蝋燭の灯りが、何本も燃え尽きた。</p><p>紫色の灯火が、何度も交換された。</p><p>それでも、答えは見つからなかった。</p><p>そして、ある夜。</p><p>「……あった！」</p><p>ピックバーグの声が、静かな図書館に響いた。</p><p>「何！？」</p><p>皇帝も、駆け寄った。彼の足音にしては珍しく、慌てたものだった。</p><p>古びた石板。</p><p>そこには、古代文字で、こう記されていた。</p><p>『竜王を滅ぼすことはできない。』</p><p>『ただし。』</p><p>『七つの結晶を破壊する時。』</p><p>『竜の力は失われる。』</p><p>「結晶？」</p><p>ピックバーグは、目を見開いた。</p><p>「エンドクリスタルだ！」</p><p>「奴の力の源！」</p><p>「壊せば、勝てる！」</p><p>スターリンが、勢いよく立ち上がった。</p><p>「だったら話は簡単だ！」</p><p>「ぶっ壊せばいい！」</p><p>しかし。</p><p>皇帝の顔は、険しかった。</p><p>「問題は。」</p><p>「その周囲を。」</p><p>「皇帝親衛軍ですら、近づけなかった。」</p><p>「竜の守護者たち。」</p><p>「七竜将が、守っている。」</p><p>その名を口にした皇帝の声には、わずかな苦みがあった。それが何を意味するのか、その時はまだ、誰も気づかなかった。</p><hr><h1 id="第七章-七竜将" tabindex="-1">第七章 七竜将 <a class="header-anchor" href="#第七章-七竜将" aria-label="Permalink to &quot;第七章 七竜将&quot;">​</a></h1><p>数日後。</p><p>世界連合軍。精鋭部隊が編成された。</p><p>「俺たちで行く。」</p><p>スターリンは、斧を担ぎ直した。</p><p>「当然。」</p><p>オーレックスは、黄金の剣を握り直した。</p><p>ピックバーグも、荷物を背負った。</p><p>「嫌な予感しかしないけどね。」</p><p>そして。</p><p>皇帝。</p><p>ENDER EMPEROR。</p><p>「私も行こう。」</p><p>四人は、最強部隊を率いて、エンドの最果てへと旅立った。</p><p>その先で待つのは。</p><p>炎を操る竜将。</p><p>雷を操る竜将。</p><p>氷を操る竜将。</p><p>闇を操る竜将。</p><p>そして。</p><p>最強の第一竜将。</p><p>SHADOW。</p><p>エンド帝国最強の戦士。</p><p>数千年前、皇帝と共に戦った、英雄だった。</p><p>その名を聞いた瞬間、皇帝の足が止まった。</p><p>「まさか。」</p><p>皇帝は、絶句した。</p><p>「お前まで……。」</p><p>その声には、戦の前の緊張ではなく、もっと深い、個人的な痛みがあった。</p><p>SHADOWは、静かに答えた。</p><p>「皇帝陛下。」</p><p>「長い夢でした。」</p><p>「しかし。」</p><p>「私は竜王の側につきます。」</p><p>「世界は。」</p><p>「一度終わるべきです。」</p><p>その言葉には、絶望に裏打ちされた、奇妙な静けさがあった。憎しみではない。むしろ、諦念だった。数千年生きた者だけが辿り着く、終わりへの憧憬だった。</p><hr><h1 id="第八章-英雄たち" tabindex="-1">第八章 英雄たち <a class="header-anchor" href="#第八章-英雄たち" aria-label="Permalink to &quot;第八章 英雄たち&quot;">​</a></h1><p>激戦。</p><p>四つの戦いが、同時に始まった。</p><p>スターリン対炎竜将。</p><p>ピックバーグ対雷竜将。</p><p>皇帝対氷竜将。</p><p>そして。</p><p>オーレックス。</p><p>黄金王対第一竜将SHADOW。</p><p>ガァァァン！！</p><p>黄金の剣と、黒曜石の大剣がぶつかり、衝撃波が大地を割った。</p><p>「強い……！」</p><p>スターリンも、隣の戦いの音を聞きながら、息を呑んだ。</p><p>「なんなんだこいつら！」</p><p>しかし。</p><p>「負けるか！」</p><p>スターリンの大斧が、炎竜将を打ち破った。</p><p>「はぁ……。」</p><p>「もう二度とやりたくない……。」</p><p>ピックバーグも、辛うじて、雷竜将に勝利した。手が、まだ震えていた。</p><p>皇帝も、氷竜将を倒した。</p><p>だが。</p><p>最強のSHADOW。</p><p>彼の剣は、圧倒的だった。</p><p>「黄金王。」</p><p>「あなたは、優しすぎる。」</p><p>「だから。」</p><p>「勝てない。」</p><p>ガァン！！</p><p>オーレックスの剣が、弾き飛ばされた。</p><p>「陛下！」</p><p>スターリンが、叫んだ。</p><p>その瞬間。</p><p>皇帝が、飛び込んだ。</p><p>「やめろ！」</p><p>ズドン！！</p><p>「……！」</p><p>SHADOWの剣が、皇帝の胸を貫いていた。</p><p>時間が、止まったように感じられた。</p><p>「皇帝！」</p><p>ピックバーグが、叫んだ。</p><p>SHADOWも、目を見開いた。</p><p>「陛下……？」</p><p>静寂。</p><p>倒れる皇帝。</p><p>そして。</p><p>怒り。</p><p>悲しみ。</p><p>絶望。</p><p>それらが、オーレックスの中で、一気に渦巻いた。</p><p>目から、涙が流れた。</p><p>「どうしてだ……。」</p><p>「どうして……。」</p><p>皇帝は、微笑んだ。痛みの中で、それでも、微笑んだ。</p><p>「黄金王。」</p><p>「希望を。」</p><p>「捨てるな。」</p><p>「世界を……。」</p><p>「頼んだ。」</p><p>その言葉を残し。</p><p>エンド帝国皇帝。</p><p>ENDER EMPERORは、静かに、目を閉じた。</p><p>数千年を生きた王。</p><p>最後まで、民を愛した王だった。</p><p>そして。</p><p>怒りに震えるオーレックスは、再び、黄金の剣を握った。</p><p>「SHADOW。」</p><p>「もう。」</p><p>「終わらせる。」</p><p>その時。</p><p>遠くで、エンダードラゴンの咆哮が響いた。</p><p>ゴォォォォォ！！</p><p>七つの結晶。</p><p>残るは、あと一つ。</p><p>そして。</p><p>世界の運命を決める、最後の戦いが、近づいていた。</p>',178)])])}const f=a(o,[["render",i]]);export{c as __pageData,f as default};
